struct PriorityItem {
    std::unique_ptr<int> value;

    // Ctor omitted for brevity, assume value is initialized

    // Overload operator< (Member function)
    // Essential for custom ordering in std::set or std::map keys
    bool operator<(const PriorityItem& other) const {
        // Comparison targets the managed content, not the pointer address
        return *value < *other.value;
    }

    // Overload operator== (Non-member friend function)
    friend bool operator==(const PriorityItem& a, const PriorityItem& b) {
        return *a.value == *b.value;
    }
};

// Example usage outside the class (non-member operator>)
bool operator>(const PriorityItem& a, const PriorityItem& b) {
    return *a.value > *b.value;
}
